#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    int minEdgeToggles(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> toggles(n, 0);
        auto dfs = [&](auto& self, int u, int p, int edge_state) -> void {
            for (auto [v, s] : adj[u]) {
                if (v != p) self(self, v, u, s);
            }
            int effective = edge_state ^ toggles[u];
            if (effective == 1) toggles[u] ^= 1;
        };
        dfs(dfs, 0, -1, 0);
        return accumulate(toggles.begin(), toggles.end(), 0);
    }
};

import java.util.*;

class Solution {
    public int minEdgeToggles(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }
        int[] toggles = new int[n];
        dfs(0, -1, 0, adj, toggles);
        int ans = 0;
        for (int t : toggles) ans += t;
        return ans;
    }

    private void dfs(int u, int p, int edgeState, List<List<int[]>> adj, int[] toggles) {
        for (int[] edge : adj.get(u)) {
            int v = edge[0], s = edge[1];
            if (v != p) dfs(v, u, s, adj, toggles);
        }
        int effective = edgeState ^ toggles[u];
        if (effective == 1) toggles[u] ^= 1;
    }
}

var minEdgeToggles = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, state] of edges) {
        adj[u].push([v, state]);
        adj[v].push([u, state]);
    }
    const toggles = new Int32Array(n);
    function dfs(u, p, edgeState) {
        for (const [v, s] of adj[u]) {
            if (v !== p) dfs(v, u, s);
        }
        const effective = edgeState ^ toggles[u];
        if (effective === 1) toggles[u] ^= 1;
    }
    dfs(0, -1, 0);
    return toggles.reduce((a, b) => a + b, 0);
};
